html:
{#- The contract (SP-74). Clauses are the admin's Contract template; no cost is ever printed. -#}
{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set c = contract_print(doc) -%}
{% block title %}
<table class="sp-quote-head">
	<tr>
		<td>
			<h2>{{ _("Contract") }}</h2>
			<div>{{ _("No.") }}: <span class="sp-num">{{ c.header.contract_no }}</span>{% if c.header.station %} · {{ _("Station") }} <span class="sp-num">{{ c.header.station }}</span>{% endif %}</div>
		</td>
		<td class="sp-quote-meta"><div>{{ _("Date") }}: {{ c.header.date }}</div></td>
	</tr>
	<tr>
		<td>{{ _("Customer") }}: <strong>{{ c.header.customer or "" }}</strong></td>
		<td class="sp-quote-meta">
			{%- if c.header.financing %}<div>{{ _("Financing") }}: {{ c.header.financing }}{% if c.header.bank_branch %} ({{ c.header.bank_branch }}){% endif %}</div>{% endif %}
			{%- if c.header.site %}<div>{{ _("Site") }}: {{ c.header.site }}</div>{% endif %}
		</td>
	</tr>
</table>
{% endblock %}
{% block body %}
{{ sp_block("Contract", "preamble", doc) }}

<table class="sp-table sp-contract-lines">
	<thead>
		<tr>
			<th>#</th><th>{{ _("Description") }}</th><th>{{ _("Unit") }}</th><th>{{ _("Qty") }}</th>
			<th>{{ _("Warranty (years)") }}</th><th>{{ _("Total") }}</th>
		</tr>
	</thead>
	<tbody>
	{%- for line in c.lines %}
		<tr>
			<td class="sp-num">{{ line.no }}</td>
			<td>{{ line.description or "" }}</td>
			<td>{{ _(line.uom) if line.uom else "" }}</td>
			<td class="sp-num">{{ frappe.format(line.qty, {"fieldtype": "Float"}) }}</td>
			<td class="sp-num sp-warranty">{{ frappe.format(line.warranty_years, {"fieldtype": "Float"}) if line.warranty_years else "" }}</td>
			<td class="sp-amount">{{ money(line.amount, c.totals.currency) }}</td>
		</tr>
	{%- endfor %}
	</tbody>
</table>

<table class="sp-quote-totals">
	{%- if c.totals.discount %}
	<tr><td>{{ _("Subtotal") }}</td><td class="sp-amount">{{ money(c.totals.subtotal, c.totals.currency) }}</td></tr>
	<tr><td>{{ _("Discount") }}</td><td class="sp-amount">- {{ money(c.totals.discount, c.totals.currency) }}</td></tr>
	{%- endif %}
	<tr class="sp-quote-grand"><td>{{ _("Total") }}</td><td class="sp-amount">{{ money(c.totals.total, c.totals.currency) }}</td></tr>
</table>
<p class="sp-words">{{ _("Only") }} {{ c.totals.words }} {{ _("no more") }}</p>

{%- for block in sp_blocks("Contract", doc, ["preamble"]) %}{{ block }}{% endfor %}

{%- if c.schedule or c.cheques %}
<div class="sp-contract-annex">
	<h3>{{ _("Annex: payment schedule") }}</h3>
	{%- if c.schedule %}
	<table class="sp-table sp-contract-schedule">
		<thead><tr><th>{{ _("Due Date") }}</th><th>{{ _("Description") }}</th><th>{{ _("Amount") }}</th></tr></thead>
		<tbody>
		{%- for row in c.schedule %}
			<tr><td>{{ row.due_date }}</td><td>{{ row.description }}</td><td class="sp-amount">{{ money(row.amount, c.totals.currency) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
	{%- endif %}
	{%- if c.cheques %}
	<h3>{{ _("Postal Cheques") }}</h3>
	<table class="sp-table sp-contract-cheques">
		<thead><tr><th>{{ _("Cheque No.") }}</th><th>{{ _("Bank") }}</th><th>{{ _("Due Date") }}</th><th>{{ _("Amount") }}</th></tr></thead>
		<tbody>
		{%- for row in c.cheques %}
			<tr><td class="sp-num">{{ row.cheque_no }}</td><td>{{ row.bank }}</td><td>{{ row.due_date }}</td><td class="sp-amount">{{ money(row.amount, c.totals.currency) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
	{%- endif %}
</div>
{%- endif %}
{% endblock %}
{% block signatures %}
{{ signature_block(_("The second party (the customer)"), _("The first party (Smart Power)")) }}
{% endblock %}
